import * as T from '../assets/three.module.js';
export function createEffects(scene,blocked=()=>null){
 const active=[],bullets=[],v=new T.Vector3();const sphere=new T.SphereGeometry(1,8,6);let glow;
 {const c=document.createElement('canvas');c.width=c.height=64;const x=c.getContext('2d'),g=x.createRadialGradient(32,32,0,32,32,32);g.addColorStop(0,'#fff');g.addColorStop(.13,'#fff');g.addColorStop(.35,'#ffffff90');g.addColorStop(1,'#ffffff00');x.fillStyle=g;x.fillRect(0,0,64,64);glow=new T.CanvasTexture(c);}
 function sparks(position,color,count=50,force=3){const data=new Float32Array(count*3),vel=[];for(let i=0;i<count;i++){data.set([position.x,position.y,position.z],i*3);vel.push(new T.Vector3((Math.random()-.5)*force,Math.random()*force,(Math.random()-.5)*force));}const g=new T.BufferGeometry();g.setAttribute('position',new T.BufferAttribute(data,3));const mat=new T.PointsMaterial({color,size:.18,map:glow,transparent:true,depthWrite:false,blending:T.AdditiveBlending});const mesh=new T.Points(g,mat);mesh.frustumCulled=false;scene.add(mesh);active.push({age:0,duration:1.1,mesh,update(dt,t){for(let i=0;i<count;i++){vel[i].y-=dt*2;data[i*3]+=vel[i].x*dt;data[i*3+1]+=vel[i].y*dt;data[i*3+2]+=vel[i].z*dt;}g.attributes.position.needsUpdate=true;mat.opacity=1-t/1.1;}});}
 function ring(position,color,radius=2,duration=.7){const mesh=new T.Mesh(new T.TorusGeometry(1,.025,6,60),new T.MeshBasicMaterial({color,transparent:true,opacity:.9,depthWrite:false,blending:T.AdditiveBlending}));mesh.position.copy(position);mesh.rotation.x=-Math.PI/2;scene.add(mesh);active.push({age:0,duration,mesh,update(dt,t){mesh.scale.setScalar(.1+t/duration*radius);mesh.material.opacity=1-t/duration;}});}
 function shield(target,duration=2.6){const mesh=new T.Mesh(new T.IcosahedronGeometry(1.3,2),new T.MeshBasicMaterial({color:'#8fe6ff',wireframe:true,transparent:true,opacity:.3,depthWrite:false,blending:T.AdditiveBlending}));scene.add(mesh);active.push({age:0,duration,mesh,update(dt,t){mesh.position.copy(target).y+=1.15;mesh.rotation.y=t*.3;mesh.material.opacity=Math.min(.38,(duration-t)*.5);}});ring(target.clone().add(new T.Vector3(0,.08,0)),'#9ae6ff',2.5,.8);}
 function projectile(from,to,{color='#ffd392',hostile=false,damage=20,onHit,fast=false}={}){if(bullets.length>30)return;const root=new T.Group(),core=new T.Mesh(sphere,new T.MeshBasicMaterial({color}));core.scale.setScalar(.09);root.add(core);const halo=new T.Sprite(new T.SpriteMaterial({map:glow,color,transparent:true,depthWrite:false,blending:T.AdditiveBlending}));halo.scale.set(.65,.65,1);root.add(halo);root.position.copy(from);const trailGeo=new T.BufferGeometry(),positions=new Float32Array(45);for(let i=0;i<15;i++)positions.set(from.toArray(),i*3);trailGeo.setAttribute('position',new T.BufferAttribute(positions,3));const trail=new T.Points(trailGeo,new T.PointsMaterial({color,map:glow,size:.22,transparent:true,opacity:.7,depthWrite:false,blending:T.AdditiveBlending}));trail.frustumCulled=false;scene.add(root,trail);bullets.push({root,trail,positions,direction:to.clone().sub(from).normalize(),destination:to.clone(),speed:hostile?9:fast?55:35,hostile,damage,onHit,age:0});}
 function freeEffect(e){scene.remove(e.mesh);e.mesh.geometry?.dispose();e.mesh.material?.dispose();}
 function freeBullet(b){scene.remove(b.root,b.trail);b.root.children.forEach(m=>m.material.dispose());b.trail.geometry.dispose();b.trail.material.dispose();}
 function update(dt,player,onDamage){for(let i=active.length-1;i>=0;i--){const e=active[i];e.age+=dt;if(e.age>=e.duration){freeEffect(e);active.splice(i,1);}else e.update(dt,e.age);}for(let i=bullets.length-1;i>=0;i--){const b=bullets[i];b.age+=dt;const step=b.speed*dt,remain=b.root.position.distanceTo(b.destination);const prev=b.root.position.clone();b.root.position.addScaledVector(b.direction,Math.min(step,remain));const obstruction=blocked(prev,b.root.position);if(obstruction)b.root.position.set(obstruction.x,obstruction.y,obstruction.z);b.positions.copyWithin(3,0,42);b.positions.set(b.root.position.toArray(),0);b.trail.geometry.attributes.position.needsUpdate=true;const hit=b.hostile&&b.root.position.distanceTo(v.copy(player).add(new T.Vector3(0,1,0)))<.85;if(obstruction||hit||remain<step+.1||b.age>5){if(hit&&!obstruction)onDamage(b.damage);if(!obstruction&&!b.hostile&&remain<step+.1)b.onHit?.();sparks(b.root.position,b.hostile?'#ba89fa':'#f3c987',22,2);freeBullet(b);bullets.splice(i,1);}}}
 function clear(){active.splice(0).forEach(freeEffect);bullets.splice(0).forEach(freeBullet);}
 return{sparks,ring,shield,projectile,update,clear};
}
export function createAudio(){let context,enabled=false,ambient;function init(){context??=new (window.AudioContext||window.webkitAudioContext)();context.resume();}function note(f=220,t=.16,type='sine',volume=.04){if(!enabled||!context)return;const o=context.createOscillator(),g=context.createGain();o.type=type;o.frequency.setValueAtTime(f,context.currentTime);o.frequency.exponentialRampToValueAtTime(Math.max(35,f*.52),context.currentTime+t);g.gain.setValueAtTime(volume,context.currentTime);g.gain.exponentialRampToValueAtTime(.001,context.currentTime+t);o.connect(g);g.connect(context.destination);o.start();o.stop(context.currentTime+t);}return{toggle(){enabled=!enabled;if(enabled){init();ambient=context.createOscillator();const gain=context.createGain();ambient.frequency.value=73.42;gain.gain.value=.006;ambient.connect(gain);gain.connect(context.destination);ambient.start();}else{ambient?.stop();ambient=null;}return enabled;},note,step(){note(75,.06,'triangle',.014);},get enabled(){return enabled;}};}
